do {
      closed = true;
      for (var row :
          jdbc.queryForList(
              "SELECT session_id,state,progress::text AS progress FROM studio_guided_sessions")) {
        String id = String.valueOf(row.get("session_id"));
        if (generationSessionBaseline.contains(id)) {
          continue;
        }
        JsonNode progress = C.parse(String.valueOf(row.get("progress")));
        boolean assigned =
            jdbc.queryForObject(
                    "SELECT count(*) FROM studio_guided_assignments WHERE session_id=?",
                    Integer.class,
                    id)
                > 0;
        boolean terminal =
            List.of(
                    "SUCCEEDED",
                    "PUBLICATION_CONFLICT",
                    "FAILED",
                    "UNKNOWN_OUTCOME",
                    "CANCELLED",
                    "EXPIRED")
                .contains(String.valueOf(row.get("state")));
        boolean recording =
            !progress.has("executionEvidence")
                || jdbc.queryForObject(
                        "SELECT count(*) FROM studio_guided_session_recordings WHERE session_id=? AND"
                            + " state IN ('AVAILABLE','FAILED','UNAVAILABLE')",
                        Integer.class,
                        id)
                    == 1;
        closed &=
            terminal
                && (!assigned || progress.path("teardownStatus").asText().equals("CONFIRMED"))
                && recording;
      }
      for (var row :
          jdbc.queryForList(
              "SELECT e.id,e.status,e.error_code,e.video_status,l.state AS"
                  + " ledger_state,l.attempt_id,l.admission_id FROM ui_test_executions e LEFT JOIN"
                  + " studio_dispatch_ledger l ON l.execution_id=e.id AND l.execution_accepted_at=e.started_at")) {
        UUID id = (UUID) row.get("id");
        if (generationExecutionBaseline.contains(id)) {
          continue;
        }
        boolean noSend = row.get("attempt_id") == null && row.get("admission_id") == null;
        // A RunningReaper ERROR/STALE close (P6 owner crash) is final with no video: closeByReaper
        // never settles evidence and findEvidenceUnsettled selects FINALIZING rows only. Live
        // processes are still checked below.
        boolean reaperStale =
            "ERROR".equals(row.get("status"))
                && "STALE".equals(row.get("error_code"))
                && row.get("video_status") == null;
        closed &=
            List.of("PASSED", "FAILED", "ERROR").contains(String.valueOf(row.get("status")))
                && "DONE".equals(row.get("ledger_state"))
                && (noSend
                    || reaperStale
                    || row.get("video_status") != null
                        && !"PROCESSING".equals(row.get("video_status")));
      }
      for (OwnedFixtureProcess root : OWNED_FIXTURE_PROCESSES) {
        if (root.generation == ownedGeneration && root.wrapper != null) {
          recordOwnedDescendants(root);
          closed &= root.descendants.stream().noneMatch(child -> child.handle().isAlive());
        }
      }
      if (closed) {
        return;
      }
      Thread.sleep(30); // No database transaction/session lock is held across this wait.
    } while (System.nanoTime() < until);

